INSERT INTO disc_patterns (code, name, description, jobs, is_active, updated_at)
VALUES
  ('C MURNI', 'LOGICAL THINKER', '{nama} praktis, cakap, dan kritis terhadap dirinya maupun orang lain. Ia menyukai hal yang rinci dan logis, lalu meneliti sebuah isu lebih dari sekali sebelum merasa yakin. Keputusan ia ambil dari logika, bukan dari suasana hati, dengan pertanyaan bagaimana dan mengapa. {nama} mengerjakan tugas secara sistematis, akurat, dan teliti sampai bagian kecil yang sering dilewatkan orang lain.', '["PERENCANA","TEKNIK","STATISTISI","AKADEMISI","PENGAWAS MUTU","TEKNOLOGI INFORMASI"]'::jsonb, TRUE, NOW()),
  ('D MURNI', 'ESTABLISHER', '{nama} memiliki dorongan diri yang kuat dan cenderung individualis dengan standar yang tinggi. Ia lebih suka mengurai masalah sendiri daripada menunggu kesepakatan yang panjang. Rasa mandirinya membuatnya tidak nyaman bila dikendalikan terlalu rapat, sehingga ia ingin menetapkan arah dan ukuran keberhasilan. {nama} menghindari hal yang biasa saja, mencari tantangan baru, dan ingin unggul ketika bersaing.', '["PENASIHAT HUKUM","PENJUALAN","MANAJER PRODUKSI","PERENCANAAN STRATEGIS","PENYELESAIAN MASALAH","WIRAUSAHA"]'::jsonb, TRUE, NOW()),
  ('CD', 'DESIGNER', '{nama} sangat berorientasi pada tugas dan peka terhadap masalah yang belum beres. Ia lebih memperhatikan pekerjaan yang ada daripada suasana di sekitarnya, termasuk perasaan orang lain. Pendekatannya kukuh, hati-hati, dan efektif saat memecahkan masalah yang rumit. {nama} menjaga jarak emosional agar keputusan tetap jernih, lalu menuntaskan pekerjaan dengan standar yang ia tetapkan sendiri.', '["DESAIN TEKNIS","RISET","PERENCANA","PENGAWAS MUTU","ANALIS SISTEM","TEKNIK"]'::jsonb, TRUE, NOW()),
  ('ID', 'NEGOTIATOR', 'Merupakan {nama} pemimpin integratif yang bekerja dengan dan melalui orang lain. Ia ramah, memiliki perhatian yang tinggi akan orang, dan mempunyai kemampuan untuk memperoleh hormat serta penghargaan dari berbagai tipe orang. {nama} melakukan pekerjaannya dengan cara yang bersahabat, baik dalam mencapai sasaran maupun dalam mengajak orang lain terlibat. Ia menyadari kebutuhan rekan kerjanya dan menyesuaikan pendekatan tanpa kehilangan arah pada hasil.', '["PENGAJARAN","PELATIHAN","PENEMU","PENJUALAN KHUSUS","KEUANGAN","HUBUNGAN MASYARAKAT"]'::jsonb, TRUE, NOW()),
  ('IDC', 'CONFIDENT & DETERMINED', '{nama} sangat berorientasi pada tugas dan sekaligus senang bekerja bersama orang. Ia pandai memilih orang, memimpin, dan menjaga keterampilan interpersonal saat mengejar hasil. {nama} dominan, percaya diri, dan ingin pengakuan atas apa yang ia selesaikan. Ia aktif menggerakkan pekerjaan, tetapi perlu mengingat bahwa kecepatan tidak boleh menyingkirkan aturan yang melindungi mutu.', '["MANAJEMEN UMUM","HUBUNGAN MASYARAKAT","KONSULTAN BISNIS","PENJUALAN","PEMASARAN","PRODUKSI"]'::jsonb, TRUE, NOW()),
  ('IDS', 'REFORMER', '{nama} bersahabat dan sosial, sekaligus suka mengendalikan situasi dan menjadi pemimpin. Ia menyelesaikan tugas melalui keterampilan sosialnya, peduli, dan menerima orang lain. {nama} mudah bergaul, sadar diri, dan cepat percaya pada orang yang ia anggap sejalan. Optimisme dan empatinya kuat, tetapi ia perlu menjaga agar selektivitasnya tidak membuat tim merasa terlalu dinilai.', '["PENGEMBANGAN TIM","PELATIHAN","HUBUNGAN MASYARAKAT","LAYANAN PELANGGAN","KOORDINATOR","PENYULUH"]'::jsonb, TRUE, NOW()),
  ('ISD', 'MOTIVATOR', '{nama} menampilkan gaya pemimpin pada kelompok yang tidak harus besar. Ia mendukung orang lain, sabar, dan tetap ingin pekerjaan bergerak. Sosialisasinya baik, tetapi ia membutuhkan ketegasan agar arah tidak mengambang. {nama} berorientasi pada hasil dan pelayanan, lalu menjaga agar kebutuhan akan pujian tidak mengalahkan fokus pada tugas.', '["PELATIH","SUPERVISOR TIM","LAYANAN PELANGGAN","HUBUNGAN MASYARAKAT","KOORDINATOR ACARA","PENGAJAR"]'::jsonb, TRUE, NOW()),
  ('SDC', 'INQUIRER', '{nama} sabar, terkontrol, dan penuh pertimbangan sebelum bergerak. Ia menjaga kendali diri dan tidak terburu memilih jalan. {nama} selektif terhadap orang dan situasi, lalu bekerja dengan ritme yang stabil. Ketelitiannya menjadi kekuatan, asalkan ia tidak terlalu kaku ketika keadaan menuntut penyesuaian.', '["PENELITI","ANALIS","PENGAWAS MUTU","ADMINISTRASI","TEKNISI","PERENCANA"]'::jsonb, TRUE, NOW()),
  ('SCD', 'INQUIRER', '{nama} baik secara alami dan sangat berorientasi pada rincian. Ia peduli pada orang di sekitarnya dan teliti saat menyelesaikan tugas. {nama} mempertimbangkan keadaan sebelum memutuskan, lalu sulit mengubah pendirian bila sudah yakin. Ia berhati-hati dan paling kuat ketika prosedur serta fakta tersedia dengan jelas.', '["PENGAWAS PRODUKSI","AKUNTANSI","PENELITI","ADMINISTRASI","PENGAWAS MUTU","ANALIS PASAR"]'::jsonb, TRUE, NOW()),
  ('DI', 'PENGAMBIL KEPUTUSAN', '{nama} tidak berbasa-basi dan tegas. Ia individualis, berpandangan jauh, progresif, dan mau bersaing untuk mencapai sasaran. {nama} logis, kritis, dan tajam saat memecahkan masalah, dengan minat yang luas. Ia memasang standar tinggi bagi dirinya dan orang di sekitarnya, menginginkan wewenang yang jelas, serta menyukai tugas yang baru.', '["MANAJEMEN UMUM","HUBUNGAN MASYARAKAT","KONSULTAN BISNIS","PENJUALAN","PEMASARAN","PRODUKSI"]'::jsonb, TRUE, NOW()),
  ('DIS', 'DIRECTOR', '{nama} fokus pada penyelesaian pekerjaan dan tetap menunjukkan penghargaan kepada orang lain. Ia mampu menggerakkan orang sekaligus menuntaskan tugas. Energinya sosial, sehingga ia dapat memotivasi tim tanpa melepaskan target. {nama} tampil percaya diri, meyakinkan, dan setelah memutuskan ia terus mengerjakan sampai selesai.', '["MANAJER PRODUKSI","PENJUALAN","MANAJER LAYANAN","LAYANAN PELANGGAN","TEKNOLOGI INFORMASI","PENGAJAR"]'::jsonb, TRUE, NOW()),
  ('DS', 'SELF-MOTIVATED', '{nama} objektif dan analitis. Ia ingin terlibat dalam situasi, sekaligus memberi bantuan kepada orang yang ia hormati. Motivasi utamanya datang dari target pribadi, bukan dari sorotan orang lain. Karena determinasinya kuat, {nama} sering berhasil, dengan ketenangan dan daya tahan sebagai bagian dari keberhasilan itu.', '["TEKNIK","MANAJEMEN PROYEK","RISET","ANALIS SISTEM","PEMROGRAM","TEKNOLOGI INFORMASI"]'::jsonb, TRUE, NOW()),
  ('CIS', 'MEDIATOR', '{nama} berorientasi pada orang dan mampu menggabungkan ketepatan dengan loyalitas. Ia cenderung peka dan memegang standar yang tinggi. {nama} menginginkan stabilitas serta pengakuan sosial, bersahabat, antusias, dan tidak formal. Ia menolak agresi, mengharapkan suasana yang harmonis, dan menjadi pencari fakta yang baik sebelum memutuskan.', '["HUBUNGAN MASYARAKAT","PELATIHAN","LAYANAN PELANGGAN","ADMINISTRASI","KONSELING","PENGAJAR"]'::jsonb, TRUE, NOW()),
  ('CSI', 'PRACTITIONER', '{nama} berorientasi pada orang dan mampu menggabungkan ketepatan dengan loyalitas pada ritmenya sendiri. Ia peka, memegang standar tinggi, dan ingin suasana yang dapat diperkirakan. {nama} bersahabat serta antusias, tetapi tetap terjadwal dan hati-hati terhadap kejutan. Ia menjaga harmoni dan baru bergerak setelah fakta yang ia butuhkan terkumpul.', '["PRAKTISI TEKNIS","PELATIH","ADMINISTRASI","LAYANAN PELANGGAN","ANALIS","PENGAWAS MUTU"]'::jsonb, TRUE, NOW()),
  ('ISC', 'RESPONSIVE & THOUGHTFUL', '{nama} berorientasi pada orang, lancar berkomunikasi, dan loyal. Ia sensitif, memegang standar tinggi, dan keputusannya bertumpu pada fakta serta data. {nama} sulit diam ketika suasana menuntut kehadirannya. Ia perlu lebih terus terang agar tidak terlalu subjektif, karena ia cepat akrab dan sangat memperhatikan apa yang dipikirkan orang lain.', '["PERSONALIA","PELATIHAN","PENGAJARAN","AKUNTANSI","LAYANAN PELANGGAN","HUBUNGAN MASYARAKAT"]'::jsonb, TRUE, NOW()),
  ('ICS', 'RESPONSIVE & THOUGHTFUL', '{nama} menggabungkan energi komunikasi dengan kebutuhan akan mutu. Ia banyak bicara, ingin pengakuan, dan tetap mencoba menjaga kualitas pekerjaan. {nama} mudah bersosialisasi, kadang terlalu banyak, sehingga fokusnya terpecah. Ia dapat diandalkan ketika peran dan tenggat dijelaskan dengan ramah serta jelas.', '["PENGAJARAN","PELATIHAN","LAYANAN PELANGGAN","HUBUNGAN MASYARAKAT","AKUNTANSI","HOSPITALITI"]'::jsonb, TRUE, NOW()),
  ('S MURNI', 'SPECIALIST', '{nama} konsisten dan berusaha menjaga lingkungan yang tidak berubah-ubah. Ia bekerja baik dengan berbagai kepribadian karena perilakunya terkendali dan rendah hati. {nama} sabar, loyal, dan suka menolong, sementara persahabatan ia kembangkan dengan lambat dan selektif. Ia nyaman berada di belakang layar, sistematis, dan tidak mengejar peran pemimpin bila tidak diminta.', '["ADMINISTRASI","TEKNIK","RISET","RITEL","AKUNTANSI","DUKUNGAN OPERASIONAL"]'::jsonb, TRUE, NOW()),
  ('CS', 'PERFECTIONIST', '{nama} berpikir sistematis dan cenderung mengikuti prosedur, baik dalam kerja maupun dalam urusan pribadi. Ia teratur, teliti, dan fokus pada rincian. {nama} bertindak hati-hati, diplomatis, dan jarang menentang rekan secara terbuka. Ia mengharapkan akurasi serta standar yang tinggi, dan dapat terjebak pada detail bila harus memutuskan tanpa petunjuk yang jelas.', '["PENGAWAS MUTU","AKUNTANSI","ADMINISTRASI","ARSIPARIS","ANALIS DATA","PERENCANA"]'::jsonb, TRUE, NOW()),
  ('SC', 'PEACEMAKER', '{nama} baik secara alami dan sangat berorientasi pada rincian. Ia peduli pada orang di sekitarnya dan menjaga kualitas penyelesaian tugas. {nama} mempertimbangkan lingkungannya sebelum memutuskan agar dampaknya tidak merugikan orang lain. Ia menginginkan kedamaian, loyal, dan tidak suka perubahan mendadak.', '["MANAJER KANTOR","SUPERVISOR PRODUKSI","AKUNTAN","ENTRI DATA","LAYANAN PELANGGAN","ADMINISTRASI"]'::jsonb, TRUE, NOW()),
  ('DC', 'CHALLENGER', '{nama} peka terhadap masalah dan kreatif dalam memecahkannya. Ia dapat menyelesaikan tugas penting dalam waktu singkat karena keputusannya kuat. {nama} tekun, reaksinya cepat, dan banyak memberi ide yang tetap berfokus pada pekerjaan. Usaha pada ketepatan mengimbangi keinginannya pada hasil yang terukur, dan ia perlu dijaga agar standar itu tidak membebani tim.', '["MANAJEMEN TEKNIK","KEUANGAN","PERENCANAAN PRODUKSI","RISET","PENGAWAS MUTU","ANALIS"]'::jsonb, TRUE, NOW()),
  ('DIC', 'CHANCELLOR', '{nama} menggabungkan kesenangan dengan pekerjaan ketika melakukan sesuatu. Ia terlihat menyukai hubungan dengan sesama, tetapi juga mampu mengerjakan hal yang rinci. {nama} ingin melakukan segala sesuatu dengan tepat. Ia ramah secara alami, menikmati interaksi, lalu menilai orang dan tugas secara hati-hati.', '["MANAJEMEN TEKNIS","TEKNIK","KEUANGAN","KONSULTAN BISNIS","TEKNOLOGI INFORMASI","PENGAJAR"]'::jsonb, TRUE, NOW()),
  ('DSI', 'DIRECTOR', '{nama} objektif dan analitis, serta ingin terlibat ketika situasi menuntut keputusan. Ia memberi bantuan dan dukungan, tetapi tetap berorientasi pada pekerjaannya. {nama} menyukai hubungan dengan sesama dan termotivasi oleh target pribadi. Determinasi, ketenangan, dan daya tahannya membuatnya sering berhasil sampai sasaran tercapai.', '["MANAJEMEN PRODUKSI","PENJUALAN","MANAJER LAYANAN","LAYANAN PELANGGAN","SUPERVISOR","KOORDINATOR"]'::jsonb, TRUE, NOW()),
  ('DSC', 'DIRECTOR', '{nama} objektif, analitis, dan ingin berada di dalam situasi, bukan hanya mengamati dari pinggir. Ia memberi dukungan kepada orang yang ia hormati sambil menjaga orientasi pada tugas. {nama} tenang, stabil, dan tahan lama saat tekanan naik. Kemandirian serta kecermatannya membuatnya dapat diandalkan pada peran yang membutuhkan arah dan ketekunan.', '["SUPERVISOR PRODUKSI","MANAJEMEN LAYANAN","PENJUALAN LAYANAN","OPERASIONAL","ADMINISTRASI","KOORDINATOR"]'::jsonb, TRUE, NOW()),
  ('DCI', 'CHALLENGER', '{nama} peka terhadap permasalahan dan kreatif mencari jalan keluar. Ia menuntaskan tugas penting dengan keputusan yang kuat dan reaksi yang cepat. {nama} meneliti berbagai kemungkinan sebelum memilih solusi, lalu banyak memberi ide yang tetap menempel pada pekerjaan. Ketepatan menjadi penyeimbang ambisinya pada hasil.', '["RISET DAN PENGEMBANGAN","ANALIS SISTEM","PENJUALAN TEKNIS","PENGAJAR","TEKNIK","PENGAWAS MUTU"]'::jsonb, TRUE, NOW()),
  ('DCS', 'CHALLENGER', '{nama} peka pada masalah dan tidak berhenti pada solusi pertama. Ia tekun, keputusannya kuat, dan reaksinya cepat ketika situasi mendesak. {nama} mengejar kemungkinan yang ada, lalu mengerjakan ide dengan fokus pada pekerjaan. Usaha pada ketepatan mengimbangi dorongannya untuk melihat hasil yang terukur.', '["TEKNIK","PRODUKSI","KEUANGAN","PENGAWAS MUTU","PERENCANA","ANALIS"]'::jsonb, TRUE, NOW()),
  ('I MURNI', 'COMMUNICATOR', 'Merupakan {nama} yang antusias dan optimistis. Ia lebih suka mencapai sasarannya melalui orang lain dan senang berhubungan dengan sesamanya. {nama} tidak suka bekerja sendirian terlalu lama dan perasaannya biasanya tampak jelas bagi orang di sekitarnya. Ia tidak memaksakan ide, tetapi mengajak dengan semangat, sehingga tindak lanjut perlu dijaga agar tidak tertinggal.', '["PROMOSI","PEMASARAN","HUBUNGAN MASYARAKAT","PENGAJARAN","HOSPITALITI","KEHUMASAN"]'::jsonb, TRUE, NOW()),
  ('IS', 'ADVISOR', '{nama} mengesankan orang dengan kehangatan, simpati, dan pengertian. Ia tenang pada sebagian besar situasi sosial dan jarang sengaja membuat orang lain tidak nyaman. Banyak orang datang kepadanya karena ia terlihat sebagai pendengar yang baik. {nama} tidak memaksakan ide, toleran, dan sering menjadi penjaga damai di kelompoknya.', '["PERSONALIA","KESEJAHTERAAN","PELATIHAN","PERHOTELAN","KEPERAWATAN","SUMBER DAYA MANUSIA"]'::jsonb, TRUE, NOW()),
  ('IC', 'ASSESSOR', '{nama} ramah, suka berteman, dan tetap nyaman walaupun berhadapan dengan orang yang baru dikenal. Ia mudah mengembangkan hubungan baru, tetapi mampu mengendalikan diri. {nama} sangat sosial dan cenderung menjaga suasana agar tidak tegang. Secara alami ia menjaga mutu, menerima kritik selama disampaikan dengan hormat, dan suka membantu tugas orang lain terlihat jelas.', '["PENGAJARAN","PELATIHAN","PENEMU","PENJUALAN KHUSUS","KEUANGAN","HUBUNGAN MASYARAKAT"]'::jsonb, TRUE, NOW()),
  ('ICD', 'ASSESSOR', '{nama} analitis, berhati-hati, dan ramah ketika ia merasa nyaman. Ia terbiasa dengan orang asing dan dapat mengembangkan hubungan baru bila ia menginginkannya. {nama} mampu mengendalikan diri sampai jarang menimbulkan rasa tersinggung. Ia peduli, tetap ramah, dan memusatkan perhatian pada penyelesaian tugas dengan mutu yang ia jaga sendiri.', '["PENJUALAN TEKNIS","KEUANGAN","TEKNIK","KONSULTAN","PELATIHAN","HUBUNGAN MASYARAKAT"]'::jsonb, TRUE, NOW()),
  ('SD', 'SELF-MOTIVATED', '{nama} objektif dan analitis. Ia ingin terlibat dalam situasi dan juga ingin memberi bantuan serta dukungan. Motivasi internalnya berasal dari target pribadi, sementara ia tetap menyukai orang-orang di sekitarnya. Karena determinasinya kuat, {nama} sering berhasil, dengan ketenangan dan daya tahan sebagai penyumbang utama.', '["TEKNIK","PRODUKSI","PENELITI","AKUNTANSI","SUPERVISOR","ANALIS"]'::jsonb, TRUE, NOW()),
  ('SI', 'ADVISOR', '{nama} menampilkan kehangatan, simpati, dan pengertian yang mudah dikenali. Ia tenang dalam situasi sosial dan jarang menyakiti orang lain dengan sengaja. Orang datang kepadanya karena ia pendengar yang baik. {nama} tidak memaksakan ide, menerima kritik dengan sabar, dan sering berdiri sebagai penjaga damai.', '["PERSONALIA","PELATIHAN","PENGAJARAN","LAYANAN PELANGGAN","HUBUNGAN MASYARAKAT","KONSELING"]'::jsonb, TRUE, NOW()),
  ('SDI', 'DIRECTOR', '{nama} objektif dan analitis, serta ingin masuk ke dalam situasi daripada hanya menunggu. Ia memberi bantuan kepada orang yang ia hormati dan tetap termotivasi oleh target pribadi. {nama} berorientasi pada pekerjaan, tetapi menyukai hubungan dengan sesama. Karakternya tenang dan daya tahannya tinggi, sehingga ia ulet sampai sasaran selesai.', '["SUPERVISOR PRODUKSI","PENJUALAN LAYANAN","MANAJEMEN KANTOR","DISTRIBUSI","LAYANAN PELANGGAN","KOORDINATOR"]'::jsonb, TRUE, NOW()),
  ('SID', 'ADVISOR', '{nama} mengesankan orang dengan kehangatan dan pengertian, sambil tetap membawa ketegasan yang tidak keras. Ia tenang pada situasi sosial dan tidak memaksakan ide kepada orang lain. {nama} kurang nyaman memberi perintah, menerima kritik, dan menjaga damai. Ketika ia sudah yakin, ia bergerak bersama orang, bukan dengan mendesak mereka.', '["PERSONALIA","PELATIHAN","PENGAJARAN","LAYANAN PELANGGAN","ADMINISTRASI","PENDAMPING"]'::jsonb, TRUE, NOW()),
  ('SIC', 'ADVOCATE', '{nama} stabil dan ramah. Ia berusaha membangun hubungan yang positif, baik di tempat kerja maupun di rumah. {nama} dapat menjadi sangat berorientasi pada rincian ketika situasi memintanya, tetapi secara keseluruhan ia cenderung menjaga jalannya sendiri. Setelah memutuskan, ia sulit mengubah pendirian dan akan memihak bila merasa ada yang tidak adil.', '["LAYANAN PELANGGAN","SUPERVISOR","PEMROGRAM","AKUNTANSI","ADMINISTRASI","PENDAMPING"]'::jsonb, TRUE, NOW()),
  ('SCI', 'ADVOCATE', '{nama} stabil, ramah, dan berusaha menjaga hubungan yang positif. Ia dapat menajamkan perhatian pada rincian ketika situasi meminta, lalu kembali pada cara kerjanya yang mandiri. {nama} teguh pada pendirian, mendukung pihak yang lemah, dan ingin diterima sebagai anggota tim. Setelah yakin, ia dapat diandalkan untuk menuntaskan bagiannya.', '["PENGAJARAN","KONSELING","LAYANAN PELANGGAN","ADMINISTRASI","PELATIHAN","HOSPITALITI"]'::jsonb, TRUE, NOW()),
  ('CI', 'ASSESSOR', '{nama} analitis, berhati-hati, dan ramah saat merasa nyaman. Ia terbiasa dengan orang asing karena dapat menilai lalu menyesuaikan diri dalam hubungan itu. {nama} mudah mengembangkan hubungan baru ketika ia mau, dan umumnya mampu mengendalikan diri. Orientasinya pada mutu membuat ritme kerjanya mudah diramalkan.', '["PENJUALAN TEKNIS","HUBUNGAN MASYARAKAT","PENGAJAR","PELATIHAN","HOSPITALITI","KONSULTAN"]'::jsonb, TRUE, NOW()),
  ('CDI', 'CHALLENGER', '{nama} sangat berorientasi pada tugas dan peka terhadap permasalahan. Ia lebih memperhatikan pekerjaan yang ada daripada perasaan di sekitarnya. {nama} kukuh dan menjaga jarak agar keputusan tetap berdasarkan fakta. Ia tidak mudah percaya sebelum bukti terkumpul, dan paling andal ketika mutu menjadi ukuran utama.', '["TEKNIK","RISET","PERENCANAAN","PENJUALAN TEKNIS","ANALIS SISTEM","PENGAJAR"]'::jsonb, TRUE, NOW()),
  ('CDS', 'CONTEMPLATOR', '{nama} berorientasi pada rincian dan memegang standar yang tinggi untuk dirinya. Ia logis, analitis, dan selalu melihat ada ruang untuk perbaikan. {nama} cenderung kompetitif dan ingin menghasilkan pekerjaan dengan mutu terbaik. Ia sebenarnya peka terhadap orang, tetapi sifat logisnya menutupi hal itu, dan ia suka dihargai karena kualitas kerjanya.', '["TEKNIK","RISET","PRODUKSI","AKUNTAN","PENGAWAS MUTU","ANALIS PASAR"]'::jsonb, TRUE, NOW()),
  ('CID', 'ASSESSOR', '{nama} analitis dan berhati-hati, tetapi tetap ramah ketika suasana terasa aman. Ia terbiasa dengan orang baru dan dapat membangun hubungan bila ia memilih untuk itu. {nama} mengendalikan diri, peduli, dan memusatkan perhatian pada penyelesaian tugas. Ia paling kuat ketika boleh menggabungkan analisis dengan percakapan yang hangat.', '["PENJUALAN KHUSUS","KEUANGAN","KONSULTAN","PENGAJAR","ANALIS","HUBUNGAN MASYARAKAT"]'::jsonb, TRUE, NOW()),
  ('CSD', 'PRECISIONIST', '{nama} berpikir sistematis dan cenderung mengikuti prosedur dalam kehidupan pribadi maupun pekerjaannya. Ia teratur, memiliki perencanaan yang baik, teliti, dan fokus pada rincian. {nama} bertindak bijaksana, diplomatis, dan jarang menentang rekan kerjanya dengan sengaja. Ia mengharapkan akurasi yang tinggi dan menginginkan petunjuk yang jelas, tanpa perubahan mendadak.', '["TEKNIK","RISET","PRODUKSI","MANAJER KEUANGAN","PENGAWAS MUTU","PERENCANA"]'::jsonb, TRUE, NOW())
INSERT INTO disc_subtraits (pair_key, label_id, pair_label, narrative, updated_at)
VALUES
  ('DI', 'Efisiensi', 'Efisiensi (D/I)', '{nama} bergerak cepat dari gagasan ke tindakan dan tidak suka energi tim terbuang pada putaran yang tidak menghasilkan. Ia menyusun prioritas dengan tegas, lalu mengajak orang lain ikut pada ritme itu melalui penjelasan yang langsung. Pembicaraan yang berputar membuatnya tidak sabar, sehingga ia memotong jalan menuju keputusan. {nama} mengukur hari yang baik dari jumlah hal yang benar-benar selesai, bukan dari lamanya diskusi. Ia tetap bisa hangat, tetapi kehangatan itu dipakai untuk membuka jalan, bukan untuk memperpanjang suasana. Bila prosedur terasa memperlambat hasil, ia akan mencari cara yang lebih pendek dan perlu diingatkan mana batas yang tidak boleh dilewati.', NOW()),
  ('DS', 'Motivasi Diri', 'Motivasi Diri (D/S)', '{nama} menyalakan kerjanya dari target pribadi, bukan dari sorotan atau desakan orang lain. Ia tenang di luar, tetapi di dalam ada dorongan untuk menyelesaikan apa yang sudah ia pegang. Perubahan mendadak tidak ia sukai, namun ia tetap maju bila sasaran terasa adil dan jelas. {nama} tidak membutuhkan banyak pengawasan untuk memulai, asalkan wewenangnya tidak dicabut di tengah jalan. Ia menghargai orang yang konsisten dan akan menjaga mereka yang ia hormati. Ketika suasana menjadi lambat, ia menaikkan tempo dengan cara yang terkendali, bukan dengan keramaian.', NOW()),
  ('DC', 'Kemandirian', 'Kemandirian (D/C)', '{nama} ingin memegang kendali atas cara kerja dan standar hasilnya sendiri. Ia tidak nyaman bila setiap langkah harus disetujui orang lain, terutama bila alasan persetujuan itu tidak rasional. Keputusan ia ambil dari fakta yang ia kumpulkan, lalu ia jalankan tanpa banyak mencari persetujuan sosial. {nama} menjaga jarak secukupnya agar penilaiannya tidak kabur oleh suasana kelompok. Ia menghormati aturan yang masuk akal dan menolak aturan yang hanya memperlambat. Kemandirian ini menjadi kekuatan bila batas wewenangnya ditulis sejak awal.', NOW()),
  ('ID', 'Keramahan', 'Keramahan (I/D)', '{nama} membuka hubungan dengan sikap yang hangat dan mudah diingat. Ia ingin disukai, tetapi tidak melepaskan keinginan untuk mempengaruhi arah pembicaraan. Orang baru cepat merasa diterima karena ia memberi perhatian yang tampak tulus. {nama} menggunakan keramahan itu untuk melancarkan kerja sama, bukan hanya untuk mengisi suasana. Ia kurang nyaman bila suasana menjadi dingin atau kaku terlalu lama. Di balik senyumnya tetap ada dorongan agar urusan yang ia anggap penting segera diputuskan.', NOW()),
  ('IS', 'Antusiasme', 'Antusiasme (I/S)', '{nama} membawa energi yang mudah menular ketika sebuah gagasan baru muncul. Ia berbicara dengan semangat, mengajak orang lain melihat sisi yang menyenangkan dari pekerjaan, dan tidak suka suasana yang muram. Antusiasme itu stabil bila hubungan di sekitarnya terasa aman. {nama} dapat kehilangan daya bila dikritik secara keras di depan orang atau bila ritme kerja berubah tanpa penjelasan. Ia paling berguna sebagai penyebar semangat pada awal tugas dan sebagai perekat saat tim mulai lelah. Tindak lanjut yang rinci perlu ditemani pengingat, karena perhatiannya mudah berpindah ke hal yang lebih hidup.', NOW()),
  ('IC', 'Kepercayaan Diri', 'Kepercayaan Diri (I/C)', '{nama} jarang sekali ragu pada dirinya, nyaman pada berbagai macam situasi, dan mudah bergaul dengan orang baru. Ia menyampaikan gagasan dengan nada yang yakin, termasuk ketika audiensnya belum ia kenal. Tekanan sosial jarang membuatnya mundur, karena ia memakai kehangatan untuk membuka percakapan dan menjaga suasana. {nama} percaya bahwa ia dapat menyesuaikan diri tanpa kehilangan kendali atas pesan yang ingin disampaikan. Keyakinan ini membuatnya cepat mengambil peran di kelompok baru, sambil tetap menjaga mutu hasil yang ia janjikan. Saat menerima kritik, ia tidak mudah goyah, lalu menata ulang cara kerjanya agar tetap terlihat kompeten dan dapat diandalkan.', NOW()),
  ('SD', 'Kesabaran', 'Kesabaran (S/D)', '{nama} tidak terburu memaksa hasil pada hari pertama. Ia memberi waktu pada orang dan proses, lalu tetap memegang arah yang ingin ia capai. Kesabaran itu bukan sikap pasif. {nama} menggunakannya untuk meredakan ketegangan sebelum keputusan yang lebih tegas diambil. Ia tidak suka benturan terbuka dan akan mencari jalan yang menjaga hubungan. Bila tekanan terus naik tanpa penjelasan, kesabarannya menipis dan ia menjadi lebih diam daripada berdebat.', NOW()),
  ('SI', 'Kehati-hatian', 'Kehati-hatian (S/I)', '{nama} menimbang dampak perkataannya sebelum berbicara, terutama bila suasana sedang rapuh. Ia tidak ingin menjadi pusat perhatian bila hal itu membuat orang lain tidak nyaman. Kehati-hatian ini membuatnya pendengar yang baik dan rekan yang jarang mempermalukan orang. {nama} bergerak lebih pelan saat ide masih mentah, karena ia ingin yakin bahwa langkahnya tidak merugikan kelompok. Ia perlu didorong untuk menyuarakan pendapat lebih awal, sebelum keputusan diambil orang lain. Setelah merasa aman, ia dapat memberi masukan yang halus tetapi tepat.', NOW()),
  ('SC', 'Ketekunan', 'Ketekunan (S/C)', '{nama} bertahan pada tugas yang panjang tanpa membutuhkan sorotan. Ia mengulang pemeriksaan, menjaga urutan, dan tidak mudah meninggalkan pekerjaan di tengah jalan. Ritme yang stabil lebih ia sukai daripada lonjakan semangat yang cepat padam. {nama} menjadi andalan pada pekerjaan yang menuntut konsistensi dan akurasi. Perubahan mendadak mengganggu ketekunannya, sehingga ia perlu diberi alasan dan waktu penyesuaian. Hasilnya sering rapi justru karena ia tidak terburu pindah ke hal yang lebih ramai.', NOW()),
  ('CD', 'Kerja Sama', 'Kerja Sama (C/D)', '{nama} mau bekerja bersama, asalkan peran, aturan, dan ukuran mutu sudah jelas. Ia tidak mencari keramaian, tetapi ia juga tidak menolak koordinasi yang masuk akal. Kerja sama baginya berarti pembagian tugas yang rapi, bukan sekadar kehadiran dalam diskusi. {nama} akan mendukung keputusan kelompok bila data yang mendasarinya dapat ia terima. Ia keberatan secara tenang ketika standar dilonggarkan tanpa alasan. Dalam tim yang menghargai ketelitian, ia menjadi mitra yang dapat diandalkan dan tidak berebut panggung.', NOW()),
  ('CI', 'Ketelitian', 'Ketelitian (C/I)', '{nama} memperhatikan angka, urutan, dan janji kecil yang mudah dilupakan orang lain. Ia tidak puas dengan kesan umum bila rinciannya belum cocok. Ketelitian itu ia sampaikan dengan cara yang masih bisa diterima, karena ia tetap peduli pada hubungan. {nama} memeriksa ulang sebelum nama atau hasilnya tampil di depan orang. Kesalahan yang berulang membuatnya tidak nyaman, termasuk kesalahan yang ia buat sendiri. Ia paling berguna pada pekerjaan yang menggabungkan komunikasi dengan kebutuhan akan bukti yang rapi.', NOW()),
  ('CS', 'Kepekaan', 'Kepekaan (C/S)', '{nama} cepat menangkap suasana yang tidak diucapkan, lalu menimbangnya dengan standar yang ia pegang. Ia peka terhadap kritik, perubahan nada, dan ketidakteraturan. Kepekaan ini membuatnya hati-hati agar tidak menyakiti orang, tetapi juga membuatnya waspada bila mutu mulai longgar. {nama} membutuhkan lingkungan yang dapat diperkirakan agar perasaannya tidak terus dalam keadaan siaga. Ketika merasa aman, ia memberi perhatian yang teliti dan setia. Ketika merasa dinilai tidak adil, ia menarik diri lebih dulu sebelum berbicara.', NOW()),
  ('BALANCE', 'Keseimbangan', 'Keseimbangan (D/I/S/C)', '{nama} menampilkan keempat dimensi pada tingkat yang berdekatan, sehingga tidak ada satu gaya yang menonjol secara tajam. Ia dapat berpindah antara ketegasan, kehangatan, kestabilan, dan ketelitian sesuai tuntutan situasi. Keseimbangan ini membuatnya fleksibel, tetapi juga membuat orang lain sulit membaca prioritas utamanya. {nama} bekerja paling baik ketika peran, batas wewenang, dan ukuran keberhasilan dijelaskan sejak awal. Tanpa arah itu, ia dapat terlihat ragu memilih gaya mana yang harus dikedepankan. Dengan kejelasan tersebut, ia mampu menyesuaikan diri tanpa kehilangan rasa diri.', NOW())
INSERT INTO disc_graph_meanings (graph_key, title, meaning, updated_at)
VALUES
  ('g1', 'DESKRIPSI PERILAKU ADAPTASI', 'Graph 1 (MOST) menggambarkan Perilaku Adaptasi (Public Self), yaitu bagaimana individu menyesuaikan gaya perilaku, pola komunikasi, dan pendekatan kerjanya demi memenuhi tuntutan lingkungan kerja atau harapan sekitar.', NOW()),
  ('g2', 'DESKRIPSI KEPRIBADIAN ASLI', 'Graph 2 (LEAST) menggambarkan Perilaku Saat Tekanan (Private Self), yaitu respons alami dan naluriah individu saat menghadapi tekanan, stres, atau kondisi tantangan yang mendesak.', NOW()),
  ('g3', 'DESKRIPSI PERSEPSI DIRI', 'Graph 3 (CHANGE / DIFFERENCE) menggambarkan Perilaku Integratif (Integrated Self / Perilaku Asli), yaitu gambaran persepsi diri individu secara menyeluruh yang menggabungkan kepribadian inti dengan bentuk adaptasi lingkungannya.', NOW())
